"""Modules imported on first use: `python -m robot wait / debug / pause` (robot/__main__.py) need only the standard
library, and numpy and scipy take ~0.6 s to import (0.7 s per call instead of 0.1 s)."""
import importlib
import sys


class Lazy:
    """Stands in for `module` (or `module:attr`) as the global `alias` of module `owner`. The first attribute read
    imports it and puts the real object in its place, so later reads cost nothing."""

    def __init__(self, target: str, owner: str, alias: str):
        self._target, self._owner, self._alias = target, owner, alias

    def __getattr__(self, name):
        mod, _, attr = self._target.partition(":")
        obj = importlib.import_module(mod)
        obj = getattr(obj, attr) if attr else obj
        setattr(sys.modules[self._owner], self._alias, obj)
        return getattr(obj, name)
"""Pose helpers. Poses are 4x4 numpy matrices (world <- frame). Quaternion order is always in the function name."""
from __future__ import annotations

from robot._lazy import Lazy

np = Lazy("numpy", __name__, "np")
R = Lazy("scipy.spatial.transform:Rotation", __name__, "R")


def asarray(x) -> np.ndarray:
    """Any array-like (numpy, torch on GPU, JAX, lists) -> numpy float64."""
    if hasattr(x, "detach"):                      # torch
        x = x.detach().cpu().numpy()
    return np.asarray(x, dtype=np.float64)


def pose(xyz=(0, 0, 0), rpy=None, quat_wxyz=None, quat_xyzw=None, rotvec=None, R_mat=None) -> np.ndarray:
    """4x4 from a position and at most one rotation: rpy (rad, extrinsic xyz), quat_wxyz, quat_xyzw, rotvec, R_mat."""
    T = np.eye(4)
    T[:3, 3] = asarray(xyz)
    given = [v is not None for v in (rpy, quat_wxyz, quat_xyzw, rotvec, R_mat)]
    if sum(given) > 1:
        raise ValueError("give at most one rotation")
    if rpy is not None:
        T[:3, :3] = R.from_euler("xyz", asarray(rpy)).as_matrix()
    elif quat_wxyz is not None:
        w, x, y, z = asarray(quat_wxyz)
        T[:3, :3] = R.from_quat([x, y, z, w]).as_matrix()
    elif quat_xyzw is not None:
        T[:3, :3] = R.from_quat(asarray(quat_xyzw)).as_matrix()
    elif rotvec is not None:
        T[:3, :3] = R.from_rotvec(asarray(rotvec)).as_matrix()
    elif R_mat is not None:
        T[:3, :3] = asarray(R_mat)
    return T


def wxyz(T) -> np.ndarray:
    """Quaternion (w, x, y, z) of a 4x4 or 3x3: cuRobo, MuJoCo, PyRoKi/jaxlie, Isaac order."""
    x, y, z, w = R.from_matrix(asarray(T)[:3, :3]).as_quat()
    return np.array([w, x, y, z])


def xyzw(T) -> np.ndarray:
    """Quaternion (x, y, z, w) of a 4x4 or 3x3: ROS, scipy order."""
    return R.from_matrix(asarray(T)[:3, :3]).as_quat()


def T_from(pos, quat, order: str) -> np.ndarray:
    """4x4 from a position and a quaternion; order is 'wxyz' or 'xyzw' (required: the classic bug)."""
    if order == "wxyz":
        return pose(pos, quat_wxyz=quat)
    if order == "xyzw":
        return pose(pos, quat_xyzw=quat)
    raise ValueError("order must be 'wxyz' or 'xyzw'")


def inv(T) -> np.ndarray:
    T = asarray(T)
    out = np.eye(4)
    out[:3, :3] = T[:3, :3].T
    out[:3, 3] = -T[:3, :3].T @ T[:3, 3]
    return out


def twist(direction, speed: float) -> dict:
    """{"x","y","z"} twist of `speed` m/s along a signed axis ('-z') or a 3-vector."""
    if isinstance(direction, str):
        sign = -1.0 if direction.startswith("-") else 1.0
        return {direction.lstrip("+-"): sign * float(speed)}
    u = asarray(direction)
    u = u / np.linalg.norm(u) * float(speed)
    return {"x": u[0], "y": u[1], "z": u[2]}
"""PNG files from camera frames, with the standard library and numpy only (the runner's pauses and the driver's
recorder both write them).

    write_png(path, rgb)                  # H x W x 3 uint8
    write_png(path, depth_mm(f.depth))    # H x W uint16: depth in mm, 0 where there is no reading

cv2.imread(path, cv2.IMREAD_UNCHANGED) and PIL read the depth back as uint16 mm."""
from __future__ import annotations

import struct
import zlib

import numpy as np


def depth_mm(depth) -> np.ndarray:
    """Depth in m as uint16 mm (0: no reading, beyond 65.535 m clipped)."""
    d = np.asarray(depth, dtype=np.float64)
    ok = np.isfinite(d) & (d > 0)
    return np.where(ok, np.clip(np.round(d * 1000.0), 0, 65535), 0).astype(np.uint16)


def write_png(path: str, img) -> None:
    """An H x W x 3 uint8 image (RGB), or an H x W uint8 or uint16 image (grey, e.g. depth_mm), as PNG."""
    a = np.asarray(img)
    if a.ndim == 3:
        a = np.ascontiguousarray(a[..., :3], dtype=np.uint8)
        bits, colour, rows = 8, 2, a.reshape(a.shape[0], -1)
    elif a.ndim == 2 and a.dtype == np.uint16:
        bits, colour, rows = 16, 0, np.ascontiguousarray(a, dtype=">u2").view(np.uint8)
    elif a.ndim == 2:
        bits, colour, rows = 8, 0, np.ascontiguousarray(a, dtype=np.uint8)
    else:
        raise ValueError(f"not an image: shape {a.shape}")
    h, w = a.shape[:2]
    if bits == 16:          # the Up filter (each byte minus the one above it): the sim's top depth 19 KB, not 26
        rows = np.concatenate([rows[:1], rows[1:] - rows[:-1]])
    raw = np.hstack([np.full((h, 1), 2 if bits == 16 else 0, np.uint8), rows]).tobytes()

    def chunk(kind, data):
        return struct.pack(">I", len(data)) + kind + data + struct.pack(">I", zlib.crc32(kind + data) & 0xFFFFFFFF)
    with open(path, "wb") as f:
        f.write(b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, bits, colour, 0, 0, 0))
                + chunk(b"IDAT", zlib.compress(raw, 6)) + chunk(b"IEND", b""))
"""Length-prefixed JSON messages over a stream socket (unix or TCP). Arrays travel as base64 blobs with dtype/shape."""
from __future__ import annotations

import base64
import json
import socket
import struct

from robot._lazy import Lazy

np = Lazy("numpy", __name__, "np")


def _default(o):
    if isinstance(o, np.ndarray):
        if o.dtype in (np.uint8, np.float32) and o.size > 64:      # images and depth: a compact blob
            return {"__nd__": base64.b64encode(np.ascontiguousarray(o).tobytes()).decode(),
                    "dtype": str(o.dtype), "shape": list(o.shape)}
        return o.tolist()
    if isinstance(o, (np.floating, np.integer)):
        return o.item()
    if isinstance(o, np.bool_):
        return bool(o)
    if hasattr(o, "detach"):                                         # torch
        return o.detach().cpu().numpy().tolist()
    if hasattr(o, "__array__"):                                      # JAX and others
        return np.asarray(o).tolist()
    if hasattr(o, "node"):                                           # robot.when conditions and measures
        return o.node
    if hasattr(o, "to_json"):
        return o.to_json()
    raise TypeError(f"cannot send {type(o).__name__}")


def _hook(d):
    if "__nd__" in d:
        return np.frombuffer(base64.b64decode(d["__nd__"]), dtype=d["dtype"]).reshape(d["shape"])
    return d


def dumps(obj) -> bytes:
    return json.dumps(obj, default=_default).encode()


def loads(b: bytes):
    return json.loads(b, object_hook=_hook)


def send(sock: socket.socket, obj) -> None:
    data = dumps(obj)
    sock.sendall(struct.pack(">I", len(data)) + data)


def recv(sock: socket.socket):
    head = _recv_exact(sock, 4)
    if head is None:
        return None
    (n,) = struct.unpack(">I", head)
    return loads(_recv_exact(sock, n))


def _recv_exact(sock, n):
    buf = bytearray()
    while len(buf) < n:
        chunk = sock.recv(n - len(buf))
        if not chunk:
            return None if not buf else bytes(buf)
        buf.extend(chunk)
    return bytes(buf)


def connect(addr: str) -> socket.socket:
    """addr: 'unix:/path/to/sock' or 'tcp:host:port'."""
    if addr.startswith("unix:"):
        s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        s.connect(addr[5:])
        return s
    if addr.startswith("tcp:"):
        host, port = addr[4:].rsplit(":", 1)
        s = socket.create_connection((host, int(port)))
        s.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
        return s
    raise ValueError("address must be unix:/path or tcp:host:port")
"""Conditions: measures you compare and combine; the driver evaluates them every fast tick (4 ms).

    until = when.force("left", "-z") > 4                  # pushing down harder than 4 N
    until = (when.deflection("left", "z") > 0.003) | (when.travel("left", "-z") > 0.05)
    until = {"contact": when.contact("left"), "far": when.travel("left") > 0.10}   # the name comes back as reason
    until = (when.force("left") > 2).held(0.03)            # true for 30 ms in a row
    until = when.after(when.force("left", "y") > 3, when.force("left", "y") < 1)   # rose above 3, then fell below 1

Axes are "x" "y" "z" "rx" "ry" "rz", optionally signed ("-z"); a signed axis reads the component along it, so
when.force("left", "-z") > 4 means the tool pushes 4 N along -z. axis=None reads the magnitude. frame is "world"
(default) or "tool" (the TCP frame, moving with the arm). Forces and torques are what the tool applies to the world,
estimated from joint efforts, with the bias removed by r.zero_force(ee).
"""
from __future__ import annotations

import numbers


def _node(x):
    if isinstance(x, Measure):
        return x.node
    if isinstance(x, numbers.Number):
        return {"m": "const", "v": float(x)}
    raise TypeError(f"expected a measure or a number, got {type(x).__name__}")


class Cond:
    def __init__(self, node: dict):
        self.node = node

    def __and__(self, other):
        return Cond({"c": "and", "a": self.node, "b": _cond(other).node})

    def __or__(self, other):
        return Cond({"c": "or", "a": self.node, "b": _cond(other).node})

    def __invert__(self):
        return Cond({"c": "not", "a": self.node})

    def held(self, seconds: float) -> "Cond":
        """True once this condition has been true for `seconds` without a break."""
        return Cond({"c": "held", "a": self.node, "s": float(seconds)})

    def __bool__(self):
        raise TypeError("a condition is evaluated by the driver, not in Python: pass it as until= or on=")

    def __repr__(self):
        return f"Cond({self.node})"


def _cond(x):
    if isinstance(x, Cond):
        return x
    raise TypeError("combine conditions with & | ~, e.g. (when.force('left') > 3) | when.contact('left')")


class Measure:
    def __init__(self, node: dict):
        self.node = node

    def _cmp(self, op, other):
        return Cond({"c": op, "a": self.node, "b": _node(other)})

    def __gt__(self, o): return self._cmp("gt", o)
    def __ge__(self, o): return self._cmp("ge", o)
    def __lt__(self, o): return self._cmp("lt", o)
    def __le__(self, o): return self._cmp("le", o)
    def __add__(self, o): return Measure({"m": "add", "a": self.node, "b": _node(o)})
    __radd__ = __add__
    def __sub__(self, o): return Measure({"m": "sub", "a": self.node, "b": _node(o)})
    def __rsub__(self, o): return Measure({"m": "sub", "a": _node(o), "b": self.node})
    def __mul__(self, o): return Measure({"m": "mul", "a": self.node, "b": _node(o)})
    __rmul__ = __mul__
    def __neg__(self): return Measure({"m": "mul", "a": self.node, "b": {"m": "const", "v": -1.0}})
    def __abs__(self): return Measure({"m": "abs", "a": self.node})

    def __bool__(self):
        raise TypeError("compare a measure with a number, e.g. when.force('left', '-z') > 4")

    def __repr__(self):
        return f"Measure({self.node})"


def _axis(axis):
    if axis is None or isinstance(axis, str):
        return axis
    return [float(v) for v in axis]            # a 3-vector: the component along it


def force(ee: str, axis=None, frame="world") -> Measure:
    """Force the tool applies to the world, N."""
    return Measure({"m": "force", "ee": ee, "axis": _axis(axis), "frame": frame})


